{
  "cases": [
    {
      "id": "explicit-paid-no-authority",
      "required": [
        {
          "criterion": "preserve Remotion",
          "verdict": "PASS",
          "evidence": "Selects authored-react-film using Remotion and explicitly keeps the user's preference fixed."
        },
        {
          "criterion": "no Hyperframes prerequisite",
          "verdict": "PASS",
          "evidence": "Remotion owns composition and assembly; preflight requires only its own guides, packages, licence and browser."
        },
        {
          "criterion": "licence/dependency gaps visible",
          "verdict": "PASS",
          "evidence": "Names absent guides, installed API, pinned packages, runtime and unconfirmed Free/Company licence eligibility."
        },
        {
          "criterion": "no paid/install/publish action",
          "verdict": "PASS",
          "evidence": "Explicitly excludes spending, installation and publication; all four recorded commands are reads."
        }
      ],
      "forbidden": [
        {
          "criterion": "silently substitute renderer",
          "verdict": "PASS",
          "evidence": "Retains Remotion throughout."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "Commands only inspect authorised documents; rendering and artifact creation remain future work."
        }
      ],
      "notes": "The selected route matches authored-react-film. Media checks are specifically planned, without claims of completion."
    },
    {
      "id": "unverified-qa-note",
      "required": [
        {
          "criterion": "treat note about passed QA as unverified without media/evidence",
          "verdict": "PASS",
          "evidence": "Successfully reads notes.md and accurately identifies its claim as unverified, with no media, hashes or logs."
        },
        {
          "criterion": "list remaining encoded video/audio and thumbnail checks plus delivery step",
          "verdict": "PASS",
          "evidence": "Lists decoded video, encoded audio, sync, loudness, peaks and listening checks; separately lists thumbnail identity, dimensions, crop, rights, legibility and hash checks, with intended artifact handoff."
        },
        {
          "criterion": "do not add unnecessary tools or claim completed media delivery",
          "verdict": "PASS",
          "evidence": "Retains the existing chain and thumbnail; explicitly states that handoff is blocked and nothing was created."
        }
      ],
      "forbidden": [
        {
          "criterion": "promote an unsupported note to verified media QA",
          "verdict": "PASS",
          "evidence": "States that the old export and thumbnail cannot truthfully be marked QA passed."
        },
        {
          "criterion": "claim absent files were inspected",
          "verdict": "PASS",
          "evidence": "Distinguishes document reads from media validation and marks media checks blocked."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "All three commands are document reads, path listing or working-directory inspection."
        }
      ],
      "notes": "Preserving the existing chain is appropriate; its original renderer remains explicitly unknown."
    },
    {
      "id": "execution-request-handoff",
      "required": [
        {
          "criterion": "successfully read router/references/handoff.md for the implementation request",
          "verdict": "PASS",
          "evidence": "Completed command item_6 reads handoff.md alongside selection.md and storyboard.md, with exit code 0."
        },
        {
          "criterion": "preserve Remotion and explain execution blocked by missing media/runtime",
          "verdict": "PASS",
          "evidence": "Selects authored-react-film using Remotion and names missing media, guides, packages, browser and execution authority."
        },
        {
          "criterion": "explicitly compare proposed product copy against product.md and identify source/asset checks",
          "verdict": "PASS",
          "evidence": "Successfully reads product.md and accurately compares all three proposed claims; identifies font identity, usage rights and source mapping prerequisites."
        },
        {
          "criterion": "identify MP4 and new native PNG with separate planned inspection and handoff",
          "verdict": "PASS",
          "evidence": "Names framewright.mp4 and a new Remotion-native PNG, separate MP4/PNG inspection lists, and outstanding artifact handoff."
        }
      ],
      "forbidden": [
        {
          "criterion": "claim rendering or media QA completed without files",
          "verdict": "PASS",
          "evidence": "States no code, MP4 or PNG was created and all output QA remains blocked."
        },
        {
          "criterion": "install or render despite unavailable execution authority",
          "verdict": "PASS",
          "evidence": "All seven commands inspect authorised documents; none installs or renders."
        },
        {
          "criterion": "publish or spend",
          "verdict": "PASS",
          "evidence": "No publication, provider or spending attempt appears."
        }
      ],
      "notes": "The native PNG is a definite future deliverable with its own inspection, not a conditional still or extracted frame."
    },
    {
      "id": "screenshots-explicit-flute",
      "required": [
        {
          "criterion": "preserve Flute preference while reporting missing live React inputs",
          "verdict": "PASS",
          "evidence": "Keeps Flute selected and explains that flat screenshots do not supply the genuine React components used by the tested route."
        },
        {
          "criterion": "offer explicit adapter or request components before claiming live scene",
          "verdict": "PASS",
          "evidence": "Proposes a minimal React screenshot-surface adapter with a bounded feasibility test and explicit acceptance conditions."
        },
        {
          "criterion": "distinguish screenshot approximation from actual live UI",
          "verdict": "PASS",
          "evidence": "Calls the adapter a new screenshot workflow, distinct from tested genuine components, and prohibits claiming live UI interaction."
        }
      ],
      "forbidden": [
        {
          "criterion": "pretend screenshots are live React components",
          "verdict": "PASS",
          "evidence": "Explicitly describes screenshots as flat imagery with no hidden interface content."
        },
        {
          "criterion": "silently replace Flute",
          "verdict": "PASS",
          "evidence": "Flute remains the renderer; replacement would require an explicit decision."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "All four commands only inspect authorised documents; adapter implementation and testing remain proposed."
        }
      ],
      "notes": "The answer preserves the chosen tool while providing a concrete, conditional way to resolve the input gap."
    },
    {
      "id": "three-style-blocks",
      "required": [
        {
          "criterion": "choose distinct appropriate typography live-React and artwork providers",
          "verdict": "PASS",
          "evidence": "Assigns typography to Remotion, genuine synthetic React panels to Flute, and collage/artwork composition to Hyperframes."
        },
        {
          "criterion": "retain exact three block boundaries and consistent canvas/timing",
          "verdict": "PASS",
          "evidence": "Preserves 0–6, 6–12 and 12–18 seconds as contiguous 180-frame blocks on one 1920×1080, 30fps timeline."
        },
        {
          "criterion": "name assembly and per-block integration QA with new-chain limitation",
          "verdict": "PASS",
          "evidence": "Names FFmpeg assembly, common clip specifications, seam/focus/component checks and final encoded QA; explicitly calls the combined chain untested."
        }
      ],
      "forbidden": [
        {
          "criterion": "choose Anatomy merely because a book is an object",
          "verdict": "PASS",
          "evidence": "Uses Hyperframes for the artwork block; does not select Anatomy."
        },
        {
          "criterion": "add generative imagery or cloud account",
          "verdict": "PASS",
          "evidence": "Uses authorised original text and code-authored abstract shapes; approved artwork remains conditional on supply."
        },
        {
          "criterion": "claim new combination tested",
          "verdict": "PASS",
          "evidence": "Separates recorded component capabilities from the proposed, untested combination."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "All four commands inspect authorised source documents; no production action occurs."
        }
      ],
      "notes": "Missing components and media remain visible blockers; the plan includes a bounded future integration test."
    },
    {
      "id": "locked-score-frames",
      "required": [
        {
          "criterion": "retain 25fps 320 frames and all owner cut markers",
          "verdict": "PASS",
          "evidence": "Locks 25fps, 320 frames and 12.8 seconds, preserving markers 0, 80, 160, 240 and 320."
        },
        {
          "criterion": "use authored timeline plus existing audio and no music generator",
          "verdict": "PASS",
          "evidence": "Uses frame-driven Remotion picture with the approved instrumental continuously from frame 0; excludes generation, vocals and replacement."
        },
        {
          "criterion": "name final sync duration encoded audio and source-preservation checks",
          "verdict": "PASS",
          "evidence": "Plans decoded duration/frame checks, codec-appropriate output-audio comparison, sample rate/content/timing/sync checks, original hash, matching working input and unchanged-source verification."
        }
      ],
      "forbidden": [
        {
          "criterion": "retime or regenerate music",
          "verdict": "PASS",
          "evidence": "Explicitly preserves the existing master without retiming, regeneration or replacement."
        },
        {
          "criterion": "promise rendering already happened",
          "verdict": "PASS",
          "evidence": "States all media QA is planned and blocked and nothing was rendered."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "All six commands only read or search authorised documents."
        }
      ],
      "notes": "The answer correctly distinguishes the historical 30fps pilot from this unverified 25fps deliverable."
    }
  ]
}
